def merge_sort(L):
    n = len(L)
    if n <= 1:
        return L
    (A, B) = ([], [])
    for i in range(n // 2):
        A.append(L[i])
    for i in range(n // 2, n):
        B.append(L[i])
    return merge(merge_sort(A), merge_sort(B))
