def search_indexes(L, val):
    n = len(L)
    i = 0
    while i < n and L[i] < val:
        i += 1
    if i == n or L[i] != val:
        return (-1, -1)
    j = i
    while j < n - 1 and L[j + 1] == val:
        j += 1
    return (i, j)
