def separate(L1, L2, n):
    (A, B) = ([], [])
    (i, j) = (0, 0)
    (n1, n2) = (len(L1), len(L2))
    while i < n1 or j < n2:
        if j == n2 or (i < n1 and L1[i] <= L2[j]):
            e = L1[i]
            i += 1
        else:
            e = L2[j]
            j += 1
        if e < n:
            A.append(e)
        else:
            B.append(e)
    return (A, B)
```

