def hill(L):
    if len(L) == 0:
        raise Exception("Empty list")
    i = 0
    n = len(L)
    while i < n - 1 and L[i] < L[i + 1]:
        i = i + 1
    top = L[i]
    i = i + 1
    while i < n - 1 and L[i] > L[i + 1]:
        i = i + 1
    if i >= n - 1:
        return top
    else:
